mapper.select:
SELECT r.reservation_code AS reservationCode, r.class_code AS classCode, r.member_code AS memberCode, r.schedule_code AS scheduleCode, r.reservation_date AS reservationDate, r.people_number AS peopleNum, r.status AS status, c.price AS price, c.name AS className,
/* 💡 공방/크리에이터 활동명 추가 */ cr.activity_name AS activityName,
img.image AS classImg FROM reservation r JOIN class c ON r.class_code = c.class_code
/* 💡 creator 테이블 LEFT JOIN 추가 */ LEFT JOIN creator cr ON c.operator_code = cr.operator_code
LEFT JOIN class_img img ON c.class_code = img.class_code AND img.type = '대표' AND img.sort_order = 1 WHERE r.class_code = #{classCode} AND r.member_code = #{memberCode} AND ROWNUM = 1

mapper.insert:
INSERT INTO review_img (
    review_img_code,
    review_code,
    review_img
) VALUES (
    SEQ_REVIEW_IMG.NEXTVAL,
    #{reviewCode},
    #{imagePath}
)
